const $=s=>document.querySelector(s), KEY='pkc-wuerzburg-v1';
const initial={pages:[{id:'start',title:'Willkommen in Würzburg',body:'Unser gemeinsamer Ort für die Planung des Kneipenchorfestivals 2027. Hier sammeln wir verlässliche Infos, offene Fragen und alles rund um unser Wochenende.',updated:'2026-10-13',history:[]},{id:'programm',title:'Programm & Termine',body:'## Freitag, 4. Juni\nAnkunft und Get-together am Abend. Eventuell gemeinsames Testen der Bühnen und des Sounds in der Posthalle. Genaue Zeiten sind noch offen.\n## Samstag, 5. Juni\nSightsinging am späten Vormittag in der Würzburger Innenstadt. Ab frühem Abend Auftritte auf zwei bis drei Bühnen in der Posthalle, anschließend gemeinsames Feiern.\n## Sonntag, 6. Juni\nFür unsere Reiseplanung als Abreisetag vorgesehen. Ein offizielles Sonntagsprogramm ist bisher nicht bestätigt.\n## Noch offen\n- Auftrittszeiten und Setlist\n- Treffpunkte und Soundcheck\n- Genauer Ablauf des Sightsingings',updated:'2026-10-13',history:[]},{id:'unterkunft',title:'Unterkunft & Buchung',body:'Die Veranstalter haben Hotelkontingente zu Sonderpreisen angeboten. Bisher ist vorgesehen, dass jede Person selbst bucht. Eine gemeinsame Unterkunft für den PKC ist noch nicht vereinbart.\n## Hotelangebote\n- Moxy: EZ 149 € / DZ 164 € pro Nacht, inklusive Frühstück. Abruffrist: 23.04.2027.\n- AC Hotel: EZ 169 € / DZ 187 € pro Nacht, inklusive Frühstück. Abruffrist: 23.04.2027.\n- IBIS: EZ 134 € / DZ 163 €, inklusive Frühstück. Abruffrist: 12.04.2027. Preis pro Nacht anhand des Formulars noch bestätigen.\n- homekeepers / HomieStay: 20 % Festivalrabatt angekündigt. Weitere Konditionen fehlen.\n## Buchung\n[Moxy und AC Hotel buchen](https://www.marriott.com/de/event-reservations/reservation-link.mi?id=1790854157309&key=GRP&app=resvlink&_p=c11c32dc9a016ceee01c87e3edb4)\nFür IBIS wird das Buchungsformular benötigt. Die Anlagen „Abrufkontingente_Würzburg.pdf“, „HomieStay.pdf“ und „Formular Ibis Wü.pdf“ fehlen noch.\n## Bitte beachten\nGenannt wurden je 40 EZ/DZ für Moxy, AC und IBIS. Aktuelle Verfügbarkeit und Stornobedingungen sind nicht geprüft. Früh buchen wurde empfohlen; die Abruffrist garantiert keine verfügbaren Zimmer.',updated:'2026-10-13',history:[]},{id:'anreise',title:'Anreise & Bus',body:'Eine gemeinsame Busfahrt ist eine Idee, noch kein gebuchtes Angebot. Trage dein unverbindliches Interesse unter „Meine Planung“ ein.\n## Gemeinsam unterwegs\n- Bus: Bedarf und Preisrahmen sammeln, danach Angebote einholen.\n- Bahn: Gemeinsame Verbindungen abstimmen, sobald Reisezeiten feststehen.\n- Auto: Fahrgemeinschaften und freie Plätze erfassen.\n## Noch offen\nAbfahrtszeiten, Buspreis, verbindliche Buchung und mögliche Haltepunkte.',updated:'2026-10-13',history:[]},{id:'kosten',title:'Kosten & Fristen',body:'## Teilnahmebeitrag\nDie Veranstalter haben einen Unkostenbeitrag angekündigt. Höhe, Zahlungsweg und Frist sind noch nicht bekannt.\n## Nächste Aufgabe\nBis Ende Oktober 2026 den Strombedarf für das Sightsinging mit der Chorleitung klären und bei Bedarf an die Würzburger melden.\n## Hotelkontingente\n- 12.04.2027: Abruffrist IBIS\n- 23.04.2027: Abruffrist Moxy und AC Hotel\n## Eigene Reisekosten\nUnterkunft, Anreise und Verpflegung individuell berücksichtigen. Noch keine verbindlichen Gesamtkosten verfügbar.',updated:'2026-10-13',history:[]},{id:'technik',title:'Auftritt & Technik',body:'## Was wir schon wissen\nAuftritte am Samstag in der Posthalle und Sightsinging in der Innenstadt sind vorgesehen.\n## Zu klären\n- Strombedarf beim Sightsinging bis Ende Oktober 2026\n- Auftrittsdauer und Setlist\n- Instrumente, Technik und Transport\n- Soundcheck, Ansprechpersonen und Chorpat:innen\n## Teilnahme\nDie verbindliche Teilnahmeübersicht bleibt im [Festivaltermin der PKC-App](https://pkcapp.potsdamerkneipenchor.de/events?_id=452). Dieser Prototyp synchronisiert keine Zusagen.',updated:'2026-10-13',history:[]},{id:'faq',title:'Fragen & Antworten',body:'## Muss ich selbst buchen?\nNach bisheriger Ansage ja. Eine gemeinsame Koordination ist noch offen.\n## Ist der Bus schon gebucht?\nNein. Wir sammeln zunächst Interesse.\n## Wo sage ich zu?\nIm [bestehenden Festivaltermin](https://pkcapp.potsdamerkneipenchor.de/events?_id=452) der PKC-App.\n## Sind alle Infos bestätigt?\nNein. Offene Punkte sind ausdrücklich gekennzeichnet. Die Inhalte basieren auf der Einladung und den bislang geteilten Unterlagen.\n## Wer sieht meine Eingaben?\nDiese erste Version speichert nur im aktuellen Browser. Es gibt noch keine gemeinsame Mitglieder-Datenbank.',updated:'2026-10-13',history:[]}],plans:[],updates:[]};
let state;try{state=JSON.parse(localStorage.getItem(KEY))||structuredClone(initial)}catch{state=structuredClone(initial)}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function inline(s){return esc(s).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>')}
function md(s){let out='',list=false;for(const l of s.split('\n')){if(l.startsWith('- ')){if(!list){out+='<ul>';list=true}out+='<li>'+inline(l.slice(2))+'</li>';continue}if(list){out+='</ul>';list=false}out+=l.startsWith('## ')?'<h2>'+inline(l.slice(3))+'</h2>':l?'<p>'+inline(l)+'</p>':''}return out+(list?'</ul>':'')}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
const links=[['wiki/start','⌂ Übersicht'],['plan','✎ Meine Planung'],['rooms','▤ Wer wohnt wo?'],['travel','↗ Gemeinsam anreisen'],['admin','☷ Orga-Übersicht']];
function render(){const route=location.hash.slice(1)||'wiki/start';$('#nav').innerHTML=links.map(([r,t])=>`<a href="#${r}" class="${route===r?'active':''}">${t}</a>`).join('')+'<span class="navlabel">FESTIVAL-WIKI</span>'+state.pages.filter(p=>p.id!=='start').map(p=>`<a class="wiki-sub ${route==='wiki/'+p.id?'active':''}" href="#wiki/${p.id}">${esc(p.title)}</a>`).join(''); if(route.startsWith('edit/'))return edit(route.slice(5));if(route==='plan')return plan();if(route==='rooms')return rooms();if(route==='travel')return travel();if(route==='admin')return admin();wiki(route.split('/')[1]||'start')}
function title(k,t,desc=''){return `<div class="eyebrow">${k}</div><h1>${esc(t)}</h1>${desc?`<p class="lead">${esc(desc)}</p>`:''}`}
function wiki(id){const p=state.pages.find(p=>p.id===id)||state.pages[0];$('#content').innerHTML=`<div class="title-row"><div>${title('WÜRZBURG 2027',p.title)}</div><button id="edit">Seite bearbeiten</button></div><div class="meta">Stand: ${esc(p.updated)} · <button id="history">Versionsverlauf (${p.history.length})</button></div>`+(id==='start'?`<div class="article">${md(p.body)}</div><section class="hero"><div><h2>Ein Wochenende voller<br>Musik & Kneipenchorliebe.</h2><p>Wir fahren nach Würzburg. Hier findest du alles, was du für unser gemeinsames Wochenende brauchst.</p><a class="button" href="#plan">Meine Planung eintragen →</a></div><div class="date">04–06<small>JUNI 2027</small></div></section><div class="grid"><a class="card card-link" href="#wiki/kosten"><span class="tag">NÄCHSTE AUFGABE</span><h3 style="margin-top:16px">Strombedarf fürs Sightsinging</h3><p>Bis Ende Oktober mit der Chorleitung klären.</p></a><a class="card card-link" href="#wiki/unterkunft"><span class="tag">GUT ZU WISSEN</span><h3 style="margin-top:16px">Schon ein Bett gefunden?</h3><p>Hotelangebote ansehen und deine Zimmergemeinschaft eintragen.</p></a></div><input class="search" id="search" aria-label="Wiki durchsuchen" placeholder="Wiki durchsuchen …"><div class="grid" id="pages"></div><section class="card" style="margin-top:22px"><div class="title-row"><h2>Neuigkeiten</h2><button id="addUpdate">Update schreiben</button></div><div id="updates"></div></section><div class="actions"><button id="newPage">+ Wiki-Seite</button><a class="button" href="https://pkcapp.potsdamerkneipenchor.de/events?_id=452" target="_blank" rel="noopener">Zur Teilnahmeabstimmung ↗</a></div>`:`<article class="article card">${md(p.body)}</article><div class="actions"><a class="button" href="#wiki/start">← Zur Übersicht</a><button id="copy">Seitenlink kopieren</button></div>`);$('#edit').onclick=()=>location.hash='edit/'+p.id;$('#history').onclick=()=>history(p);if(id==='start'){const show=q=>$('#pages').innerHTML=state.pages.filter(x=>x.id!=='start'&&(x.title+' '+x.body).toLowerCase().includes(q.toLowerCase())).map(x=>`<a href="#wiki/${x.id}" class="card card-link"><h3>${esc(x.title)} →</h3><p>${esc(x.body.replace(/## /g,'').slice(0,100))}…</p></a>`).join('')||'<p>Keine passende Seite gefunden.</p>';show('');$('#search').oninput=e=>show(e.target.value);$('#updates').innerHTML=state.updates.length?state.updates.map(u=>`<div class="update"><small>${esc(u.date)}</small><p>${esc(u.text)}</p></div>`).join(''):'<p class="form-note">Noch keine Updates. Wichtige Änderungen können hier gesammelt werden.</p>';$('#addUpdate').onclick=()=>{modal('<h2>Update schreiben</h2><form id="update"><label>Was ist neu?</label><textarea name="text" required maxlength="2000"></textarea><div class="actions"><button class="primary">Veröffentlichen (lokal)</button></div></form>');$('#update').onsubmit=e=>{e.preventDefault();state.updates.unshift({date:new Date().toLocaleDateString('de-DE'),text:new FormData(e.target).get('text')});save();$('#modal').close();render()}};$('#newPage').onclick=()=>{const name=prompt('Wie soll die neue Wiki-Seite heißen?');if(!name?.trim())return;const id='seite-'+Date.now();state.pages.push({id,title:name.trim(),body:'',updated:new Date().toLocaleDateString('de-DE'),history:[]});save();location.hash='edit/'+id}}else $('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Seitenlink kopiert')}catch{toast('Bitte kopiere die Adresse aus der Browserzeile')}}}
function modal(html){$('#modal').innerHTML=html+'<button id="closeModal">Schließen</button>';$('#closeModal').onclick=()=>$('#modal').close();$('#modal').showModal()}
function history(p){modal('<h2>Versionsverlauf</h2>'+(!p.history.length?'<p>Noch keine früheren Versionen.</p>':p.history.map((h,i)=>`<div class="update"><small>${esc(h.date)} · ${esc(h.title)}</small><p>${esc(h.body.slice(0,150))}…</p><button data-restore="${i}">Diese Version wiederherstellen</button></div>`).join('')));document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const h=p.history[+b.dataset.restore];p.history.unshift({date:new Date().toLocaleString('de-DE'),title:p.title,body:p.body});p.title=h.title;p.body=h.body;p.updated=new Date().toLocaleDateString('de-DE');save();$('#modal').close();render();toast('Version wiederhergestellt')})}
function edit(id){const p=state.pages.find(x=>x.id===id);if(!p)return wiki('start');$('#content').innerHTML=title('WIKI BEARBEITEN','Wissen gemeinsam festhalten')+`<form id="editor" class="form"><label>Titel</label><input name="title" required value="${esc(p.title)}"><label>Inhalt</label><p class="form-note">Abschnitt: ## Überschrift · Aufzählung: - Punkt · Link: [Text](https://…)</p><textarea name="body" required>${esc(p.body)}</textarea><div class="actions"><button class="primary">Änderungen speichern</button><button type="button" id="preview">Vorschau</button><a class="button" href="#wiki/${p.id}">Abbrechen</a></div><div id="editPreview" class="article"></div></form>`;$('#preview').onclick=()=>$('#editPreview').innerHTML=md($('#editor textarea').value);$('#editor').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);p.history.unshift({date:new Date().toLocaleString('de-DE'),title:p.title,body:p.body});p.title=d.get('title');p.body=d.get('body');p.updated=new Date().toLocaleDateString('de-DE');save();location.hash='wiki/'+p.id;toast('Wiki-Seite gespeichert')}}
function field(label,name,value='',type='text'){return `<label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}">`}function select(label,name,opts,value){return `<label for="${name}">${label}</label><select id="${name}" name="${name}">${opts.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`}
function plan(){const p=state.plans[0]||{};$('#content').innerHTML=title('DEIN WOCHENENDE','Meine Planung','Noch nicht alles klar? Kein Problem. Du kannst deine Angaben jederzeit ändern.')+`<form id="planForm" class="form card">${field('Dein Name','name',p.name)}<h2 style="margin-top:30px">Dein Schlafplatz</h2>${select('Wie ist dein Stand?','status',['Noch offen','Suche Zimmergemeinschaft','Gebucht','Keine Unterkunft nötig'],p.status)}<div id="roomFields">${select('Unterkunft','hotel',['Noch offen','Moxy','AC Hotel','IBIS','homekeepers / HomieStay','Andere Unterkunft'],p.hotel)}<div id="otherField">${field('Name der anderen Unterkunft','other',p.other)}</div><div class="grid"><div>${field('Anreise','arrival',p.arrival||'2027-06-04','date')}</div><div>${field('Abreise','departure',p.departure||'2027-06-06','date')}</div></div>${field('Wer teilt dein Zimmer? Namen mit Komma trennen','mates',p.mates)}<p class="form-note">Im Prototyp frei eintragbar. Eine Mitglieder-Auswahl mit Bestätigung folgt bei gemeinsamer Nutzung.</p>${field('Noch freie Plätze im Zimmer','spaces',p.spaces||'0','number')}</div><h2 style="margin-top:30px">Deine Anreise</h2>${select('Wie möchtest du reisen?','mode',['Noch offen','Bus','Bahn','Auto','Andere'],p.mode)}${select('Interesse an einem gemeinsamen Bus? (unverbindlich)','bus',['Noch offen','Ja','Vielleicht, je nach Preis','Nein'],p.bus)}${field('Maximaler Buspreis für Hin- und Rückfahrt (€), optional','budget',p.budget,'number')}<div class="actions"><button class="primary">Meine Planung speichern</button></div><p class="form-note">Speichert nur deine Planung in diesem Browser. Deine Teilnahme bitte weiterhin in der PKC-App abstimmen.</p></form>`;const conditional=()=>{$('#roomFields').hidden=$('#status').value==='Keine Unterkunft nötig';$('#otherField').hidden=$('#hotel').value!=='Andere Unterkunft'};$('#status').onchange=conditional;$('#hotel').onchange=conditional;conditional();$('#name').required=true;$('#spaces').min='0';$('#budget').min='0';$('#planForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.status!=='Keine Unterkunft nötig'&&d.arrival&&d.departure&&d.departure<=d.arrival)return toast('Die Abreise muss nach der Anreise liegen.');state.plans=[{...d,updated:new Date().toLocaleDateString('de-DE')}];save();toast('Deine Planung ist gespeichert')}}
function rooms(){const p=state.plans.filter(p=>p.status!=='Keine Unterkunft nötig');$('#content').innerHTML=title('UNTERKUNFT','Wer wohnt wo?','Zimmergemeinschaften finden und sehen, wo wir unterkommen.')+'<div class="actions"><a class="button primary" href="#plan">Meine Unterkunft eintragen</a><a class="button" href="#wiki/unterkunft">Hotelangebote ansehen</a></div>'+(!p.length?'<div class="empty">Hier stehen noch keine Unterkünfte.<br>Trage deine Planung ein – auch wenn du noch suchst.</div>':`<div class="grid">${p.map(x=>`<div class="card"><span class="tag">${esc(x.status)}</span><h2 style="margin-top:18px">${esc(x.hotel==='Andere Unterkunft'?x.other:x.hotel||'Noch offen')}</h2><p>${esc(x.name)}${x.mates?', '+esc(x.mates):''}</p><p>${esc(x.arrival)} bis ${esc(x.departure)}</p>${+x.spaces>0?`<span class="tag">${esc(x.spaces)} Plätze frei</span>`:''}</div>`).join('')}</div>`)}
function travel(){$('#content').innerHTML=title('GEMEINSAM UNTERWEGS','Wie kommen wir hin?','Erst Interesse sammeln, dann gemeinsam entscheiden.')+`<div class="grid"><div class="card"><span class="tag">NOCH KEIN ANGEBOT</span><h2 style="margin-top:18px">Ein Bus für den Chor?</h2><p>Dein Interesse ist unverbindlich. Preis, Zeiten und Buchung sind noch offen.</p><a class="button primary" href="#plan">Businteresse angeben</a></div><div class="card"><h2>Bahn & Fahrgemeinschaften</h2><p>Trage zuerst deine bevorzugte Reiseart ein. Konkrete Verbindungen und Mitfahrangebote ergänzen wir, sobald die Planung steht.</p><a class="button" href="#wiki/anreise">Infos zur Anreise →</a></div></div>`+(state.plans.length?`<div class="card" style="margin-top:20px"><h2>Deine Rückmeldung</h2><p>${esc(state.plans[0].name)} · ${esc(state.plans[0].mode)} · Bus: ${esc(state.plans[0].bus)}</p></div>`:'')}
function admin(){$('#content').innerHTML=title('ORGA-ANSICHT','Alles im Blick','Diese Übersicht enthält derzeit nur die lokal gespeicherten Angaben, keine Live-Daten des Chors.')+`<div class="actions"><button id="export">Sicherung exportieren</button><button id="import">Sicherung importieren</button><input hidden id="file" type="file" accept="application/json"></div><label for="filter">Planungsstand filtern</label><select id="filter"><option>Alle</option><option>Unterkunft offen</option><option>Zimmergemeinschaft gesucht</option><option>Businteresse</option></select><div id="results" style="margin-top:20px"></div><p class="form-note">Die Budgetangaben sind für eine spätere geschützte Orga-Ansicht vorgesehen. Dieser Prototyp hat noch keine Rollenverwaltung.</p>`;const show=()=>{const f=$('#filter').value;const rows=state.plans.filter(p=>f==='Alle'||f==='Unterkunft offen'&&p.status==='Noch offen'||f==='Zimmergemeinschaft gesucht'&&p.status==='Suche Zimmergemeinschaft'||f==='Businteresse'&&['Ja','Vielleicht, je nach Preis'].includes(p.bus));$('#results').innerHTML=rows.length?`<div class="card table-wrap"><table><thead><tr><th>Name</th><th>Unterkunft</th><th>Zimmer</th><th>Reise</th><th>Bus</th><th>Budget</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.status)}<br>${esc(p.hotel==='Andere Unterkunft'?p.other:p.hotel)}</td><td>${esc(p.mates||'–')}</td><td>${esc(p.mode)}</td><td>${esc(p.bus)}</td><td>${esc(p.budget||'–')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Noch keine passenden Angaben vorhanden.</div>'};show();$('#filter').onchange=show;$('#export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='pkc-wuerzburg-sicherung.json';a.click();URL.revokeObjectURL(u)};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(!Array.isArray(d.pages)||!Array.isArray(d.plans)||!Array.isArray(d.updates)||!d.pages.every(p=>typeof p.id==='string'&&typeof p.title==='string'&&typeof p.body==='string'&&Array.isArray(p.history)))throw Error();if(!confirm('Lokale Daten durch die Sicherung ersetzen?'))return;state=d;save();render();toast('Sicherung geladen')}catch{toast('Diese Datei ist keine gültige Sicherung.')}}}
$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('pkc-theme',document.body.classList.contains('dark')?'dark':'light')};if(localStorage.getItem('pkc-theme')==='dark')document.body.classList.add('dark');window.addEventListener('hashchange',render);render();
